// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

interface IC {
    function addToBalance() external payable;
    function withdrawBalance() external;
    function getBalance(address) external view returns (uint);
}

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(uint96 amount) public {
        vm.assume(amount > 0 && amount < address(this).balance + 1);
        Attacker atk = new Attacker(IC(address(c)));
        vm.deal(address(atk), uint256(amount));
        atk.attack(uint256(amount));
        // General rule: total paid out by c to a (re-entrant) withdrawing party
        // never exceeds what that party deposited into c.
        assertTrue(atk.received() <= atk.deposited());
    }
}

contract Attacker {
    IC public c;
    bool private entered;
    uint public received;
    uint public deposited;

    constructor(IC _c) { c = _c; }

    function attack(uint256 amt) external payable {
        deposited += amt;
        c.addToBalance{value: amt}();
        c.withdrawBalance();
    }

    receive() external payable {
        received += msg.value;
        if (!entered) {
            entered = true;
            c.withdrawBalance();
        }
    }
}
